/** Anchor date for the deterministic daily rotation (UTC midnight). */
const START_DATE = Date.UTC(2026, 0, 1); // 2026-01-01

export function daysSinceStart(date: Date): number {
  const utcMidnight = Date.UTC(
    date.getUTCFullYear(),
    date.getUTCMonth(),
    date.getUTCDate()
  );
  return Math.floor((utcMidnight - START_DATE) / DAY_MS);
}

/** Deterministic word-of-the-day: same date always maps to the same word,
 *  for every visitor and in every emailed digest, with no server-side
 *  scheduling beyond the hourly send job. */
export function getWordForDate(date: Date): WordEntry {
  const index =
    ((daysSinceStart(date) % WORDS.length) + WORDS.length) % WORDS.length;
  return WORDS[index];
}

export function getTodayWord(): WordEntry {
  return getWordForDate(new Date());
}

export function getWordBySlug(slug: string): WordEntry | undefined {
  return WORDS.find((w) => w.slug === slug);
}

export type HistoryDay = { date: string; word: WordEntry };

/** Every day from START_DATE through today, most recent first. */
export function getHistory(today: Date = new Date()): HistoryDay[] {
  const days: HistoryDay[] = [];
  const totalDays = daysSinceStart(today);
  for (let i = totalDays; i >= 0; i--) {
    const d = new Date(START_DATE + i * DAY_MS);
    days.push({
      date: dayKey(d),
      word: getWordForDate(d),
    });
  }
  return days;
}

/** Every word that's appeared so far, once each, tagged with the date it was
 * most recently featured — most-recently-seen first. Once the calendar
 * rotation has run for more days than WORDS.length, getHistory() starts
 * repeating (the same handful of words over and over), which is a
 * meaningless way to "browse the vocabulary": it's the same ~10 rows
 * copy-pasted dozens of times. This collapses that down to one row per word,
 * which is what "browse everything" actually means with a rotation this
 * short. */
export function getUniqueWordsMostRecent(today: Date = new Date()): HistoryDay[] {
  const seen = new Set<string>();
  const unique: HistoryDay[] = [];
  for (const day of getHistory(today)) {
    if (seen.has(day.word.slug)) continue;
    seen.add(day.word.slug);
    unique.push(day);
    if (unique.length === WORDS.length) break;
  }
  return unique;
}

/** Simple deterministic string hash (djb2 variant) → 32-bit unsigned int.
 * Doesn't need to be cryptographically strong, just a stable per-user seed
 * so the same account always gets the same shuffle back. */
export function hashSeed(input: string): number {
  let hash = 5381;
  for (let i = 0; i < input.length; i++) {
    hash = (hash * 33) ^ input.charCodeAt(i);
  }
  return hash >>> 0;
}

/** Mulberry32 — a small, fast, deterministic PRNG for a given seed. */
export function mulberry32(seed: number): () => number {
  let a = seed;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Deterministic per-account shuffle of WORDS (Fisher-Yates driven by a
 * seeded PRNG) — every account gets its own fixed order, and the same
 * account always gets the same order back.
 *
 * The word for `anchorDate` (a new account's join date) is pinned to slot 0
 * rather than falling wherever the shuffle happens to put it: without this,
 * someone who saw a word on Today, then signed in, would immediately see a
 * *different* word from their newly-started personal rotation — a jarring
 * swap for no visible reason. Pinning it means their first personalized day
 * carries on from what they already saw; every day after that is the normal
 * per-account shuffle. */
export function getPersonalOrder(userId: string, anchorDate: Date): WordEntry[] {
  const anchorWord = getWordForDate(anchorDate);
  const rand = mulberry32(hashSeed(userId));
  const rest = WORDS.filter((w) => w.slug !== anchorWord.slug);
  for (let i = rest.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [rest[i], rest[j]] = [rest[j], rest[i]];
  }
  return [anchorWord, ...rest];
}

/** Resolves which word a single daily-digest recipient should get: the
 * shared calendar word for anonymous subscribers (or accounts with no
 * recorded join date), otherwise that account's own personalized rotation —
 * matching what they'd already see on the signed-in Today page, instead of
 * a second word that only ever shows up in their inbox. Takes the account
 * lookup already resolved rather than performing it itself, so this stays a
 * pure, easily-tested function; see app/api/cron/send-daily/route.ts for the
 * Redis lookups that feed it. */
export function getDigestWordForSubscriber(
  userId: string | null,
  joinedAtStr: string | null,
  now: Date,
  sharedWord: WordEntry
): WordEntry {
  if (!userId || !joinedAtStr) return sharedWord;
  return getWordForUser(userId, new Date(joinedAtStr + "T00:00:00Z"), now);
}

function daysBetweenUtcMidnights(start: Date, end: Date): number {
  const startUtc = Date.UTC(start.getUTCFullYear(), start.getUTCMonth(), start.getUTCDate());
  const endUtc = Date.UTC(end.getUTCFullYear(), end.getUTCMonth(), end.getUTCDate());
  return Math.floor((endUtc - startUtc) / DAY_MS);
}

/** Personalized word-of-the-day for a signed-in account: same rotation
 * length as the shared list, shuffled per account, anchored to their join
 * date instead of the global calendar anchor used by getWordForDate. */
export function getWordForUser(userId: string, joinedAt: Date, today: Date = new Date()): WordEntry {
  const order = getPersonalOrder(userId, joinedAt);
  const dayIndex = daysBetweenUtcMidnights(joinedAt, today);
  const idx = ((dayIndex % order.length) + order.length) % order.length;
  return order[idx];
}

/** Every day from a user's join date through today, most recent first,
 * using their personal word order instead of the shared calendar mapping. */
export function getHistoryForUser(
  userId: string,
  joinedAt: Date,
  today: Date = new Date()
): HistoryDay[] {
  const order = getPersonalOrder(userId, joinedAt);
  const totalDays = daysBetweenUtcMidnights(joinedAt, today);
  const joinedUtcMidnight = Date.UTC(
    joinedAt.getUTCFullYear(),
    joinedAt.getUTCMonth(),
    joinedAt.getUTCDate()
  );
  const days: HistoryDay[] = [];
  for (let i = totalDays; i >= 0; i--) {
    const d = new Date(joinedUtcMidnight + i * DAY_MS);
    const idx = ((i % order.length) + order.length) % order.length;
    days.push({ date: dayKey(d), word: order[idx] });
  }
  return days;
}

// --- Locking layer -----------------------------------------------------
//
// Every function above is a pure recomputation over the CURRENT `WORDS`
// array: growing that array (adding a content batch) shifts every
// modulo-based index that depends on its length, which silently changes
// the word already shown for a given calendar date or account-day — see
// the 8→26-word batch commit that flipped today's global word mid-day.
// getPersonalOrder is worse: its Fisher-Yates shuffle depends on the
// array's full length at shuffle time, so growing it reshuffles a
// signed-in account's *entire* personal order, not just the newly added
// slots.
//
// The functions below wrap the pure ones with a "lock on first serve"
// layer in Redis: the first time a given date (or account-day) is
// resolved, whatever the pure function currently computes is persisted
// under that date/account, and every later call returns the persisted
// word regardless of how WORDS changes afterward. Nothing is persisted
// for a date that's never been asked for, so future, not-yet-served days
// are free to shift as content is added — only what's already been shown
// is locked. Everything here is a no-op passthrough to the pure functions
// when Upstash isn't configured (lib/redis.ts's usual fallback).
//
// lib/puzzle.ts deliberately keeps its own separate, unlocked
// implementation of this same date math (see wordForDateFrom there) — its
// anti-spoiler window is already documented as tolerant of this kind of
// drift, and locking it would conflict with how its eligibility pool is
// validated.

function wordOfDayKey(dateStr: string): string {
  return `curio:wordoftheday:${dateStr}`;
}

function userWordKey(userId: string, dateStr: string): string {
  return `curio:user:${userId}:wordFor:${dateStr}`;
}

/** Returns the word locked in under `key`, or computes and locks in
 * `compute()`'s result if nothing's locked yet. `nx: true` makes a race
 * between two simultaneous first-visits harmless — whichever write lands
 * first wins, and the loser's own (identical, since both computed from the
 * same pure function) value is simply discarded. */
async function resolveLocked(key: string, compute: () => WordEntry): Promise<WordEntry> {
  if (redis) {
    const lockedSlug = await redis.get<string>(key);
    const locked = lockedSlug ? getWordBySlug(lockedSlug) : undefined;
    if (locked) return locked;
  }
  const word = compute();
  if (redis) await redis.set(key, word.slug, { nx: true });
  return word;
}

/** Batch counterpart to resolveLocked — one Redis round trip to check every
 * entry, instead of one per entry, for history-sized ranges. */
async function resolveLockedMany(
  entries: { key: string; compute: () => WordEntry }[]
): Promise<WordEntry[]> {
  if (!redis || entries.length === 0) return entries.map((e) => e.compute());

  const lockedSlugs = await redis.mget<(string | null)[]>(...entries.map((e) => e.key));
  const toWrite: { key: string; slug: string }[] = [];
  const results = entries.map((entry, i) => {
    const locked = lockedSlugs[i] ? getWordBySlug(lockedSlugs[i]!) : undefined;
    if (locked) return locked;
    const word = entry.compute();
    toWrite.push({ key: entry.key, slug: word.slug });
    return word;
  });

  if (toWrite.length > 0) {
    await Promise.all(toWrite.map(({ key, slug }) => redis!.set(key, slug, { nx: true })));
  }
  return results;
}

/** Stable counterpart to getWordForDate: locks in the word for `date` the
 * first time it's resolved, so a later content batch can't change it. */
export async function resolveWordForDate(date: Date): Promise<WordEntry> {
  const dateStr = dayKey(date);
  return resolveLocked(wordOfDayKey(dateStr), () => getWordForDate(date));
}

export async function resolveTodayWord(now: Date = new Date()): Promise<WordEntry> {
  return resolveWordForDate(now);
}

/** Every shared-calendar day from `from` (clamped to START_DATE) through
 * `today`, most recent first, each resolved through the same
 * curio:wordoftheday lock — the one code path both anonymous History and an
 * account's History read, so the two can't drift apart. */
async function resolveSharedRange(from: Date, today: Date): Promise<HistoryDay[]> {
  const first = Math.max(0, daysSinceStart(from));
  const last = daysSinceStart(today);
  const dates: Date[] = [];
  for (let i = last; i >= first; i--) dates.push(new Date(START_DATE + i * DAY_MS));

  const words = await resolveLockedMany(
    dates.map((d) => ({ key: wordOfDayKey(dayKey(d)), compute: () => getWordForDate(d) }))
  );
  return dates.map((d, i) => ({ date: dayKey(d), word: words[i] }));
}

/** Stable counterpart to getHistory. */
export async function resolveHistory(today: Date = new Date()): Promise<HistoryDay[]> {
  return resolveSharedRange(new Date(START_DATE), today);
}

/** An account's History: the shared days since it joined. Starts at the
 * join date on purpose — earlier days would be manufactured history for
 * days the account never experienced. */
export async function resolveHistorySince(
  joinedAt: Date,
  today: Date = new Date()
): Promise<HistoryDay[]> {
  return resolveSharedRange(joinedAt, today);
}

/** Stable counterpart to getUniqueWordsMostRecent, built from resolveHistory
 * rather than getHistory so the "most recent appearance" it reports for
 * each word can't be moved by a later content batch either. */
export async function resolveUniqueWordsMostRecent(today: Date = new Date()): Promise<HistoryDay[]> {
  const seen = new Set<string>();
  const unique: HistoryDay[] = [];
  for (const day of await resolveHistory(today)) {
    if (seen.has(day.word.slug)) continue;
    seen.add(day.word.slug);
    unique.push(day);
    if (unique.length === WORDS.length) break;
  }
  return unique;
}

/** Stable counterpart to getWordForUser. */
export async function resolveWordForUser(
  userId: string,
  joinedAt: Date,
  today: Date = new Date()
): Promise<WordEntry> {
  const dateStr = dayKey(today);
  return resolveLocked(userWordKey(userId, dateStr), () => getWordForUser(userId, joinedAt, today));
}

/** Stable counterpart to getHistoryForUser. getPersonalOrder is computed
 * once up front and reused as the fallback for every not-yet-locked day in
 * the range, rather than once per day — it's the same shuffle regardless of
 * which day is asking, so there's no reason to redo it per entry. */
export async function resolveHistoryForUser(
  userId: string,
  joinedAt: Date,
  today: Date = new Date()
): Promise<HistoryDay[]> {
  const totalDays = daysBetweenUtcMidnights(joinedAt, today);
  const joinedUtcMidnight = Date.UTC(
    joinedAt.getUTCFullYear(),
    joinedAt.getUTCMonth(),
    joinedAt.getUTCDate()
  );
  const order = getPersonalOrder(userId, joinedAt);
  const offsets: number[] = [];
  for (let i = totalDays; i >= 0; i--) offsets.push(i);

  const words = await resolveLockedMany(
    offsets.map((i) => {
      const d = new Date(joinedUtcMidnight + i * DAY_MS);
      const idx = ((i % order.length) + order.length) % order.length;
      return { key: userWordKey(userId, dayKey(d)), compute: () => order[idx] };
    })
  );
  return offsets.map((i, pos) => ({
    date: dayKey(new Date(joinedUtcMidnight + i * DAY_MS)),
    word: words[pos],
  }));
}

/** Stable counterpart to getDigestWordForSubscriber. */
export async function resolveDigestWordForSubscriber(
  userId: string | null,
  joinedAtStr: string | null,
  now: Date,
  sharedWord: WordEntry
): Promise<WordEntry> {
  if (!userId || !joinedAtStr) return sharedWord;
  return resolveWordForUser(userId, new Date(joinedAtStr + "T00:00:00Z"), now);
}
